import sys
from decimal import Decimal, ROUND_HALF_UP


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        a, op, b_str = parts
        try:
            a = Decimal(a)
            b = Decimal(b_str)
        except ValueError:
            print("ERROR")
            continue
        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        else:
            try:
                result = round(a / b, 10, ROUND_HALF_UP)
            except ZeroDivisionError:
                print("ERROR")
                continue
        # Format the output
        if result == int(result):
            print(result)
        else:
            s = str(result)
            if "." in s:
                integer_part, fractional_part = s.split(".")
            else:
                integer_part = s
                fractional_part = ""
            stripped_integer = integer_part.lstrip("0")
            if not stripped_integer:
                stripped_integer = "0"
            result_str = stripped_integer + "." + fractional_part.rstrip("0")
            print(result_str if result_str else "0")


if __name__ == "__main__":
    main()
